// Xcode 27 refuses to build pods whose deployment target is below iOS 15, and
// a few dependencies (ReachabilitySwift, RNCAsyncStorage's resource bundle)
// still declare 12.0 / 13.4. `ios/` is generated by prebuild, so the fix lives
// here: raise every pod to the app's own target in the Podfile's post_install.
const fs = require('fs');
const path = require('path');
const { withDangerousMod } = require('expo/config-plugins');

const MARKER = '# withPodsDeploymentTarget';

module.exports = function withPodsDeploymentTarget(config) {
  return withDangerousMod(config, ['ios', async (cfg) => {
    const podfile = path.join(cfg.modRequest.platformProjectRoot, 'Podfile');
    let src = fs.readFileSync(podfile, 'utf8');
    if (!src.includes(MARKER)) {
      src = src.replace(
        /post_install do \|installer\|\n/,
        `post_install do |installer|
    ${MARKER}
    installer.pods_project.targets.each do |t|
      t.build_configurations.each do |bc|
        if bc.build_settings['IPHONEOS_DEPLOYMENT_TARGET'].to_f < 15.1
          bc.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = podfile_properties['ios.deploymentTarget'] || '16.4'
        end
      end
    end
`,
      );
      fs.writeFileSync(podfile, src);
    }
    return cfg;
  }]);
};
